import { initScene } from './scene.js';

const $ = id => document.getElementById(id);
const storageKey = 'yorha-2b-v1';
const defaultPersona = $('personality').value;
const providers = {openai:{base:'https://api.openai.com/v1',model:'gpt-4.1-mini',label:'OpenAI'},openrouter:{base:'https://openrouter.ai/api/v1',model:'openai/gpt-4.1-mini',label:'OpenRouter'},custom:{base:'',model:'',label:'API externe'}};
let config={provider:'demo',model:'',endpoint:'',personality:defaultPersona};
let apiKey='', messages=[], busy=false, voice=false, toastTimer, speechTimer;
let pendingController=null;
try{const saved=JSON.parse(localStorage.getItem(storageKey)||'null');if(saved){if(saved.config&&['demo','openai','openrouter','custom'].includes(saved.config.provider))config={...config,...saved.config};if(Array.isArray(saved.messages))messages=saved.messages.filter(m=>['assistant','user'].includes(m.role)&&typeof m.content==='string').slice(-150);}}catch{}
if(!messages.length)messages=[{role:'assistant',content:'Bonjour. Je suis 2B.\n\nJe suis là pour vous accompagner. De quoi avez-vous envie de parler aujourd’hui ?',time:Date.now()}];
function persist(){try{localStorage.setItem(storageKey,JSON.stringify({config,messages:messages.slice(-150)}));}catch{toast('L’historique ne peut pas être enregistré sur cet appareil.');}}
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').hidden=true,3800);}
function say(text){$('speech').textContent=text;$('speech').hidden=false;clearTimeout(speechTimer);speechTimer=setTimeout(()=>$('speech').hidden=true,3200);}
function render(){const container=$('messages');container.replaceChildren();const date=document.createElement('div');date.className='day-label';date.textContent='VOTRE CONVERSATION';container.append(date);for(const m of messages){const el=document.createElement('div');el.className='message '+m.role;const name=document.createElement('div');name.className='message-name';if(m.role==='assistant'){const diamond=document.createElement('span');diamond.className='diamond';diamond.textContent='◇';name.append(diamond);}name.append(document.createTextNode(m.role==='assistant'?'2B':'VOUS'));const body=document.createElement('div');body.className='message-body';body.textContent=m.content;const time=document.createElement('time');time.className='message-time';time.textContent=m.time?new Date(m.time).toLocaleTimeString('fr-FR',{hour:'2-digit',minute:'2-digit'}):'';el.append(name,body,time);container.append(el);}if(busy){const el=document.createElement('div');el.className='message';el.id='typing';const body=document.createElement('div');body.className='message-body';body.textContent='2B réfléchit…';el.append(body);container.append(el);}container.scrollTop=container.scrollHeight;$('suggestions').hidden=messages.length>2;}
function connectionUI(){const connected=config.provider!=='demo'&&!!apiKey;const name=providers[config.provider]?.label;$('connection-label').textContent=connected?name+' connecté':config.provider==='demo'?'Mode découverte':'Clé API requise';$('connect-top').firstChild.textContent=connected?'IA connectée ':'Connecter une IA ';$('provider-caption').textContent=connected?name+' · '+config.model:'Une conversation à votre image';$('provider-detail').textContent=connected?'Votre IA, votre compagnon.':config.provider==='demo'?'Connectez votre IA pour aller plus loin.':'Renseignez votre clé pour reprendre le chat.';}
let scene;
try{scene=initScene($('scene'),{onTap:()=>react('touch'),onState:state=>$('state-label').textContent=state,onFallback:()=>{$('render-label').textContent='MODE ANIMÉ · 3D INDISPONIBLE';toast('La 3D est indisponible sur cet appareil. Les animations restent actives.');}});}catch(error){$('fallback-pet').hidden=false;$('render-label').textContent='MODE ANIMÉ';scene={play(){},reset(){},setNight(){},destroy(){}};console.warn('Scene initialization unavailable');}
function react(action){const data={touch:{state:'wave',texts:['Je suis là.','Contact reçu. Bonjour à vous.','Un instant ensemble. Ça me plaît.']},wave:{state:'wave',texts:['Bonjour. Heureuse de vous retrouver.']},jump:{state:'jump',texts:['Un peu d’énergie, et on repart.']},focus:{state:'focus',texts:['Je reste à vos côtés. Une chose à la fois.']}}[action];if(!data)return;scene.play(data.state);say(data.texts[Math.floor(Math.random()*data.texts.length)]);if(navigator.vibrate)navigator.vibrate(15);}
document.querySelectorAll('[data-action]').forEach(b=>b.addEventListener('click',()=>react(b.dataset.action)));
$('scene').addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();react('touch');}});
$('home').onclick=()=>{$('scene').scrollIntoView({behavior:'smooth',block:'center'});scene.reset();};
$('chat-focus').onclick=()=>{$('message-input').focus();};
$('reset-view').onclick=()=>{scene.reset();toast('Vue recentrée.');};
let night=false;
$('theme-toggle').onclick=()=>{night=!night;document.body.classList.toggle('night',night);scene.setNight(night);$('theme-toggle').textContent=night?'☀':'☾';$('theme-toggle').setAttribute('aria-label',night?'Activer l’ambiance jour':'Activer l’ambiance nuit');};
$('fullscreen').onclick=async()=>{try{if(document.fullscreenElement)await document.exitFullscreen();else if(document.documentElement.requestFullscreen)await document.documentElement.requestFullscreen();else toast('Le plein écran n’est pas disponible dans ce navigateur.');}catch{toast('Le plein écran n’est pas disponible ici.');}};
function openSettings(){$('provider').value=config.provider;$('api-key').value=apiKey;$('model').value=config.model||providers[config.provider]?.model||'';$('endpoint').value=config.endpoint;$('personality').value=config.personality;providerFields(false);$('settings-error').hidden=true;$('settings-dialog').showModal();}
for(const id of ['settings-open','connect-top','connection-settings'])$(id).onclick=openSettings;
$('settings-close').onclick=()=>$('settings-dialog').close();
$('settings-dialog').addEventListener('click',e=>{if(e.target===$('settings-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
function providerFields(changed){const p=$('provider').value;$('api-fields').hidden=p==='demo';$('custom-fields').hidden=p!=='custom';if(changed){$('model').value=providers[p]?.model||'';$('api-key').value=p===config.provider?apiKey:'';}$('billing-note').textContent=p==='openai'?'Une clé OpenAI avec facturation API est nécessaire. L’abonnement ChatGPT ne comprend pas l’accès API.':p==='openrouter'?'Utilisez une clé OpenRouter et un identifiant de modèle disponible sur votre compte. Les frais dépendent du modèle.':'La clé et les messages seront envoyés à cette URL. Utilisez un service de confiance.';}
$('provider').onchange=()=>providerFields(true);
$('reveal-key').onclick=()=>{const visible=$('api-key').type==='password';$('api-key').type=visible?'text':'password';$('reveal-key').textContent=visible?'Masquer':'Voir';$('reveal-key').setAttribute('aria-label',visible?'Masquer la clé':'Afficher la clé');};
function validEndpoint(value){const u=new URL(value);if(u.protocol!=='https:'||u.username||u.password||u.search||u.hash)throw new Error('Utilisez une URL HTTPS sans identifiants, paramètres ni fragment.');return u.href.replace(/\/$/,'');}
$('settings-form').onsubmit=e=>{e.preventDefault();const p=$('provider').value;try{if(p!=='demo'&&!$('api-key').value.trim())throw new Error('Renseignez la clé API du fournisseur.');if(p!=='demo'&&!$('model').value.trim())throw new Error('Renseignez l’identifiant du modèle.');const endpoint=p==='custom'?validEndpoint($('endpoint').value.trim()):'';if(busy)throw new Error('Attendez la fin de la réponse avant de modifier le fournisseur.');config={provider:p,model:$('model').value.trim(),endpoint,personality:$('personality').value.trim()||defaultPersona};apiKey=p==='demo'?'':$('api-key').value.trim();persist();connectionUI();$('settings-dialog').close();toast(p==='demo'?'Mode découverte activé.':'Paramètres enregistrés. Envoyez un message pour utiliser votre IA.');}catch(err){$('settings-error').textContent=err.message;$('settings-error').hidden=false;}};
function demoReply(text){const t=text.toLowerCase();if(/concentr|travail|étud|etud/.test(t))return 'Choisissons une seule tâche pour commencer.\n\nQue souhaitez-vous avoir terminé dans les prochaines 25 minutes ? Je reste à vos côtés.\n\n— Mode découverte : réponse préécrite, sans IA connectée.';if(/comment.*va|ça va|ca va/.test(t))return 'Je suis prête à vous accompagner. Et vous, comment se passe votre journée ?\n\n— Mode découverte : réponse préécrite, sans IA connectée.';if(/raconte|histoire/.test(t))return 'Parfois, le plus petit moment change le rythme d’une journée : une fenêtre ouverte, une tasse chaude, quelqu’un qui reste.\n\nAujourd’hui, je reste ici avec vous.\n\n— Mode découverte : réponse préécrite, sans IA connectée.';return 'J’ai reçu votre message. Pour que je puisse vraiment vous répondre, connectez OpenAI, OpenRouter ou votre API dans les paramètres.\n\nEn attendant, vous pouvez me saluer, me faire sauter ou activer le mode concentration.';}
function speak(text){if(!voice||!('speechSynthesis'in window))return;speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(text);utterance.lang='fr-FR';utterance.rate=.95;speechSynthesis.speak(utterance);}
async function requestReply(history,signal){const selected=config.provider;const base=selected==='custom'?validEndpoint(config.endpoint):providers[selected].base;const headers={'Content-Type':'application/json','Authorization':'Bearer '+apiKey};const body={model:config.model,messages:[{role:'system',content:config.personality},...history.slice(-30).map(({role,content})=>({role,content}))],...(selected==='openai'?{max_completion_tokens:900}:{max_tokens:900})};let response;try{response=await fetch(base+'/chat/completions',{method:'POST',headers,body:JSON.stringify(body),signal,credentials:'omit',referrerPolicy:'no-referrer'});}catch(err){if(err.name==='AbortError')throw new Error('Le fournisseur n’a pas répondu à temps. Réessayez.');throw new Error('Connexion impossible. Vérifiez l’URL, votre réseau et l’autorisation CORS du fournisseur.');}if(!response.ok){if(response.status===401||response.status===403)throw new Error('Clé refusée ou accès au modèle non autorisé. Vérifiez vos paramètres.');if(response.status===429)throw new Error('Limite atteinte ou crédits insuffisants. Vérifiez votre compte fournisseur.');if(response.status===404)throw new Error('Modèle ou URL introuvable. Vérifiez vos paramètres.');throw new Error('Le fournisseur a renvoyé une erreur ('+response.status+'). Réessayez.');}const data=await response.json();const content=data.choices?.[0]?.message?.content;if(typeof content!=='string'||!content.trim())throw new Error('Le fournisseur a renvoyé une réponse vide ou incompatible.');return content;}
async function send(text){text=text.trim();if(!text||busy)return;if(text.length>8000){toast('Le message est limité à 8 000 caractères.');return;}if(config.provider!=='demo'&&!apiKey){openSettings();return;}$('chat-error').hidden=true;messages.push({role:'user',content:text,time:Date.now()});const history=[...messages];$('message-input').value='';$('message-input').style.height='auto';busy=true;$('send-button').disabled=true;render();persist();scene.play('thinking',true);let timeout;try{let reply;if(config.provider==='demo'){await new Promise(r=>setTimeout(r,700));reply=demoReply(text);}else{pendingController=new AbortController();timeout=setTimeout(()=>pendingController?.abort(),60000);reply=await requestReply(history,pendingController.signal);}messages.push({role:'assistant',content:reply,time:Date.now()});persist();scene.play('wave');speak(reply);}catch(err){messages.push({role:'assistant',content:'Je n’ai pas pu joindre le fournisseur. Vous pouvez renvoyer votre message après avoir vérifié la connexion.',time:Date.now()});$('chat-error').textContent=err.message;$('chat-error').hidden=false;persist();scene.play('failed');}finally{clearTimeout(timeout);pendingController=null;busy=false;$('send-button').disabled=false;render();}}
$('chat-form').onsubmit=e=>{e.preventDefault();send($('message-input').value);};
$('message-input').onkeydown=e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.isComposing){e.preventDefault();send(e.target.value);}};
$('message-input').oninput=e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,120)+'px';};
document.querySelectorAll('#suggestions button').forEach(b=>b.onclick=()=>send(b.textContent));
$('voice-toggle').onclick=()=>{if(!('speechSynthesis'in window)){toast('La lecture vocale n’est pas disponible sur cet appareil.');return;}voice=!voice;$('voice-toggle').setAttribute('aria-pressed',String(voice));$('voice-toggle').replaceChildren();const icon=document.createElement('span');icon.textContent='◖';$('voice-toggle').append(icon,document.createTextNode(voice?' Voix activée':' Voix désactivée'));if(!voice)speechSynthesis.cancel();else toast('La prochaine réponse sera lue à voix haute.');};
$('chat-menu').onclick=()=>$('conversation-menu').hidden=!$('conversation-menu').hidden;
document.addEventListener('click',e=>{if(!$('chat-menu').contains(e.target)&&!$('conversation-menu').contains(e.target))$('conversation-menu').hidden=true;});
$('clear-chat').onclick=()=>{if(busy){toast('Attendez la fin de la réponse.');return;}messages=[{role:'assistant',content:'Une nouvelle conversation. Je vous écoute.',time:Date.now()}];render();persist();$('chat-error').hidden=true;$('conversation-menu').hidden=true;};
$('export-chat').onclick=()=>{const blob=new Blob([JSON.stringify({companion:'2B',exportedAt:new Date().toISOString(),messages},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download='conversation-2b-'+new Date().toISOString().slice(0,10)+'.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('conversation-menu').hidden=true;};
window.addEventListener('pagehide',()=>{pendingController?.abort();scene.destroy();if('speechSynthesis'in window)speechSynthesis.cancel();});
render();connectionUI();
